-- composition of rule kernels L:eliminate_join x P:ProjectionPushdown (datafusion), template not_exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a2.c1 AS c0, a1.c1 AS c1 FROM (ti AS a1 JOIN (t2 AS a2 JOIN v0 AS a3 ON (a2.c0 = a3.n)) ON ((a1.c0 = a3.c0) AND FALSE))) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c3, a1.c0 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2000-01-01'::date AS c0)) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c3, a1.c0 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2000-01-01'::date AS c0)) AS kb) = 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a2.c1 AS c0, a1.c1 AS c1 FROM (ti AS a1 JOIN (t2 AS a2 JOIN v0 AS a3 ON (a2.c0 = a3.n)) ON ((a1.c0 = a3.c0) AND FALSE))) AS ka) ELSE 0 END
